from pathlib import Path
import json, uuid
NS=uuid.UUID('f6ff8c4c-b85a-4a53-8c56-72da97df8201')
def uid(s): return str(uuid.uuid5(NS,s))
def sql(s): return "'"+str(s).replace("'","''")+"'"
cats=[('quant','Quantitative Aptitude','calculate','#376BD6',['Percentages','Time & Work','Profit & Loss']),('english','English','translate','#087E83',['Vocabulary','Grammar','Comprehension']),('reasoning','Reasoning','psychology','#8051C5',['Number Series','Coding & Decoding','Logical Reasoning']),('general-awareness','General Awareness','public','#B66A13',['Indian Polity','Geography','Science'])]
lines=['-- Generated by tools/generate_seed.py. Development examples: review before publishing to students.','begin;']
for i,(slug,name,icon,color,topics) in enumerate(cats):
 lines.append(f"insert into public.categories(id,name,slug,icon,color_hex,sort_order) values ({sql(uid(slug))},{sql(name)},{sql(slug)},{sql(icon)},{sql(color)},{i}) on conflict(id) do nothing;")
 for j,t in enumerate(topics): lines.append(f"insert into public.subtopics(id,category_id,name,sort_order) values ({sql(uid(slug+t))},{sql(uid(slug))},{sql(t)},{j}) on conflict(id) do nothing;")
questions=[]
for i in range(40):
 base=(i+5)*20; pct=[5,10,15,20,25][i%5]; answer=base*pct//100
 questions.append(('quant',i,f'What is {pct}% of {base}?',[str(answer),str(answer+5),str(answer+10),str(answer+15)],f'{pct}% of {base} = {base} × {pct}/100 = {answer}.'))
for i in range(40):
 start=i+2; step=i%7+3; seq=[start+step*j for j in range(4)]; answer=start+step*4
 questions.append(('reasoning',i,'Find the next number: '+', '.join(map(str,seq))+', …',[str(answer),str(answer+1),str(answer+step),str(answer+2*step)],f'The sequence increases by {step} each time. {seq[-1]} + {step} = {answer}.'))
vocab=[('abundant','Plentiful'),('accurate','Precise'),('benevolent','Kind'),('brief','Concise'),('candid','Frank'),('cautious','Careful'),('coherent','Logical'),('competent','Capable'),('diligent','Hardworking'),('diverse','Varied'),('eager','Keen'),('evident','Obvious'),('feasible','Practical'),('fragile','Delicate'),('frugal','Thrifty'),('hostile','Unfriendly'),('humble','Modest'),('immense','Enormous'),('impartial','Unbiased'),('inevitable','Unavoidable'),('innovative','Inventive'),('lucid','Clear'),('meticulous','Thorough'),('novice','Beginner'),('obsolete','Outdated'),('optimistic','Hopeful'),('persistent','Determined'),('prudent','Sensible'),('reluctant','Unwilling'),('scarce','Rare'),('serene','Calm'),('sincere','Honest'),('skeptical','Doubtful'),('swift','Quick'),('tedious','Boring'),('tranquil','Peaceful'),('vague','Unclear'),('versatile','Adaptable'),('vital','Essential'),('weary','Tired')]
for i,(word,meaning) in enumerate(vocab):
 distractors=[vocab[(i+k)%40][1] for k in (7,15,23)]
 questions.append(('english',i,f'Choose the word closest in meaning to “{word}”.',[meaning]+distractors,f'“{word.capitalize()}” means {meaning.lower()}.'))
ga=[('Which part of the Indian Constitution contains Fundamental Rights?','Part III','Part I','Part II','Part IV'),('Which article abolishes untouchability?','Article 17','Article 14','Article 19','Article 21'),('What is the minimum age to become a member of the Lok Sabha?','25 years','21 years','30 years','35 years'),('The Directive Principles are contained in which part?','Part IV','Part II','Part III','Part V'),('How many Fundamental Duties are listed in the Constitution?','11','10','12','9'),('Who chairs the Rajya Sabha?','Vice President','President','Prime Minister','Lok Sabha Speaker'),('Which amendment lowered the voting age to 18?','61st','42nd','44th','73rd'),('Which schedule lists the recognised languages?','Eighth','Fifth','Seventh','Tenth'),('Panchayati Raj received constitutional status through which amendment?','73rd','42nd','61st','86th'),('What is the minimum age to become President of India?','35 years','25 years','30 years','40 years'),('On which date did the Constitution of India come into effect?','26 January 1950','15 August 1947','26 November 1949','2 October 1950'),('Who chaired the Constitution Drafting Committee?','B. R. Ambedkar','Jawaharlal Nehru','Rajendra Prasad','Sardar Patel'),('Which ocean lies south of India?','Indian Ocean','Pacific Ocean','Atlantic Ocean','Arctic Ocean'),('Which is the largest Indian state by area?','Rajasthan','Maharashtra','Madhya Pradesh','Uttar Pradesh'),('Which is the smallest Indian state by area?','Goa','Sikkim','Tripura','Mizoram'),('Which river flows through Delhi?','Yamuna','Ganga','Godavari','Narmada'),('Which imaginary line passes through central India?','Tropic of Cancer','Equator','Tropic of Capricorn','Arctic Circle'),('Which range separates the Indian subcontinent from the Tibetan Plateau?','Himalayas','Aravalli','Western Ghats','Satpura'),('What is the capital of Kerala?','Thiruvananthapuram','Kochi','Kozhikode','Thrissur'),('Which plateau covers much of peninsular India?','Deccan Plateau','Tibetan Plateau','Chota Nagpur Plateau','Malwa Plateau'),('Which sea lies west of India?','Arabian Sea','Red Sea','Caspian Sea','South China Sea'),('Which is the largest continent by area?','Asia','Africa','Europe','Antarctica'),('Which is the smallest continent by area?','Australia','Europe','Antarctica','South America'),('Which is the longest river in peninsular India?','Godavari','Krishna','Kaveri','Narmada'),('What is the SI unit of force?','Newton','Joule','Watt','Pascal'),('What is the chemical symbol for gold?','Au','Ag','Fe','Cu'),('Which gas do plants absorb during photosynthesis?','Carbon dioxide','Oxygen','Nitrogen','Hydrogen'),('Which organ pumps blood through the human body?','Heart','Liver','Lungs','Kidneys'),('What is the SI unit of electric current?','Ampere','Volt','Ohm','Watt'),('Which vitamin is produced by skin exposed to sunlight?','Vitamin D','Vitamin A','Vitamin B12','Vitamin C'),('What is the chemical formula of water?','H₂O','CO₂','NaCl','O₂'),('Which planet is known as the Red Planet?','Mars','Venus','Jupiter','Mercury'),('What is the closest star to Earth?','The Sun','Sirius','Polaris','Proxima Centauri'),('Which blood cells primarily carry oxygen?','Red blood cells','White blood cells','Platelets','Stem cells'),('Which part of the cell contains most genetic material?','Nucleus','Ribosome','Cell membrane','Cytoplasm'),('What is the SI unit of power?','Watt','Newton','Joule','Volt'),('What is the normal boiling point of water at sea level?','100°C','90°C','110°C','120°C'),('Which gas makes up the largest share of Earth’s atmosphere?','Nitrogen','Oxygen','Carbon dioxide','Argon'),('Which acid is found in the human stomach?','Hydrochloric acid','Sulfuric acid','Nitric acid','Acetic acid'),('What is the approximate speed of light in a vacuum?','300,000 km/s','30,000 km/s','3,000 km/s','300 km/s')]
for i,(q,a,*wrong) in enumerate(ga): questions.append(('general-awareness',i,q,[a]+wrong,f'The correct answer is {a}.'))
for slug,i,q,options,explanation in questions:
 qid=uid(slug+str(i)); category=next(c for c in cats if c[0]==slug); topic=category[4][i%3]; difficulty=['easy','medium','hard','easy','medium'][i%5]
 lines.append(f"insert into public.questions(id,category_id,subtopic_id,question_text,difficulty,time_limit_seconds,explanation,status) values ({sql(qid)},{sql(uid(slug))},{sql(uid(slug+topic))},{sql(q)},{sql(difficulty)},15,{sql(explanation)},'published') on conflict(id) do nothing;")
 for j,text in enumerate(options):
  # Rotate option positions so the sample key is not always first.
  lines.append(f"insert into public.question_options(id,question_id,option_text,is_correct,sort_order) values ({sql(uid(qid+str(j)))},{sql(qid)},{sql(text)},{str(j==0).lower()},{(j+i)%4}) on conflict(id) do nothing;")
names=['Aarav Sharma','Ananya Nair','Arjun Menon','Diya Patel','Ishaan Verma','Kavya Rao','Rohan Das','Meera Iyer','Aditya Singh','Nisha Thomas','Vikram Reddy','Sana Khan','Rahul Gupta','Sneha Pillai','Dev Kapoor','Priya Joshi','Kiran Kumar','Neha Shah','Varun Sethi','Anjali Bose']
for i,name in enumerate(names): lines.append(f"insert into public.profiles(id,full_name,profile_completed,is_bot,rating,level) values ({sql(uid('bot'+str(i)))},{sql(name)},true,true,{800+i*45},{1+i%8}) on conflict(id) do nothing;")
lines.append("insert into public.admin_users(email,role) values ('badushamc312@gmail.com','super_admin') on conflict(email) do nothing;")
for key,value in {'search_timeout_seconds':20,'questions_per_match':10,'label_bots':True,'maintenance_mode':False,'min_app_version':'0.1.0'}.items(): lines.append(f"insert into public.app_settings(key,value) values ({sql(key)},{sql(json.dumps(value))}::jsonb) on conflict(key) do nothing;")
